package com.medipanda.controller;
import com.medipanda.model.*; import com.medipanda.repository.*; import org.springframework.web.bind.annotation.*; import java.security.Principal; import java.util.*;
@RestController @RequestMapping("/api/notifications") public class NotificationController { private final NotificationRepository repo; private final UserRepository users; public NotificationController(NotificationRepository r,UserRepository u){repo=r;users=u;} @GetMapping public List<Notification> list(Principal p){User u=users.findByEmailIgnoreCaseOrPhone(p.getName(),p.getName()).orElseThrow();return repo.findTop30ByUserIdOrderByCreatedAtDesc(u.getId());}
 @GetMapping("/unread-count") public Map<String,Long> unreadCount(Principal p){User u=users.findByEmailIgnoreCaseOrPhone(p.getName(),p.getName()).orElseThrow();return Map.of("count",repo.countByUserIdAndReadFalse(u.getId()));}
 @PatchMapping("/read-all") public Map<String,Object> readAll(Principal p){User u=users.findByEmailIgnoreCaseOrPhone(p.getName(),p.getName()).orElseThrow();List<Notification> all=repo.findByUserIdAndReadFalse(u.getId());all.forEach(n->n.setRead(true));repo.saveAll(all);return Map.of("success",true);} @PatchMapping("/{id}/read") public Notification read(@PathVariable String id,Principal p){User u=users.findByEmailIgnoreCaseOrPhone(p.getName(),p.getName()).orElseThrow();Notification n=repo.findById(id).orElseThrow();if(!u.getId().equals(n.getUserId()))throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.FORBIDDEN,"Forbidden");n.setRead(true);return repo.save(n);}  @PostMapping("/device-token") public Map<String,Object> register(@RequestBody Map<String,String> b,Principal p){String t=b.get("token");if(t==null||t.isBlank()||t.length()>4096)throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.BAD_REQUEST,"Invalid device token");User u=users.findByEmailIgnoreCaseOrPhone(p.getName(),p.getName()).orElseThrow();if(u.getFcmTokens()==null)u.setFcmTokens(new ArrayList<>());if(!u.getFcmTokens().contains(t)){u.getFcmTokens().add(t);while(u.getFcmTokens().size()>5)u.getFcmTokens().remove(0);users.save(u);}return Map.of("registered",true);}
 @DeleteMapping("/device-token") public Map<String,Object> unregister(@RequestBody Map<String,String> b,Principal p){User u=users.findByEmailIgnoreCaseOrPhone(p.getName(),p.getName()).orElseThrow();if(u.getFcmTokens()!=null&&u.getFcmTokens().remove(b.get("token")))users.save(u);return Map.of("registered",false);}
}
